"""Cuaderno del estudiante, 5.º básico Lenguaje y Comunicación: OA 23 (escucha literaria de obras completas) y OA 24 (comprensión y contraste de textos orales).

Todos los textos son originales y breves (escritos para este cuaderno); no se reproducen obras reales.
La «escucha» la hace una persona adulta o el propio estudiante leyendo en voz alta el texto que viene en el enunciado.
Nota: los títulos de las clases del currículo son genéricos; este cuaderno sigue el OA oficial.
Las obras reales (cuentos, poemas, mitos, capítulos de novela) quedan para que el docente las elija y las lea.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA23, OA24 = "LE05 OA 23", "LE05 OA 24"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


CUENTO = ("En un pueblo de secano, donde hacía meses que no llovía, una pastora llamada Inés subió al cerro con su cántaro casi vacío. "
          "Allí encontró un pájaro con las alas caídas por la sed. Aunque ella también tenía sed, le dio de beber la última agua. "
          "Al terminar, el cántaro volvió a llenarse solo, y desde las nubes empezó a caer una lluvia suave sobre el pueblo.")
POEMA = ("Gotas pequeñas tocan mi ventana, / una canción de plata en la mañana. / "
         "El patio huele a tierra y a frescura, / y yo me quedo quieto, con ternura.")
LEYENDA = ("Cuentan que, hace mucho, el cerro grande del valle lloraba de noche porque extrañaba a la luna. "
           "Sus lágrimas bajaron como un arroyo y regaron el valle. Por eso, dicen los abuelos, el arroyo suena más fuerte cuando hay luna llena.")
CAP = ("Capítulo 3. Cuando Bruno llegó a la caleta, el bote azul ya no estaba. Anotó en su libreta: huellas de botas pequeñas. "
       "Su amiga Salomé dijo que seguramente alguien lo había pedido prestado. Bruno no estuvo de acuerdo: había una cuerda cortada en el muelle. "
       "Decidieron preguntar al pescador viejo, que siempre veía todo desde su banca. Ese día, sin embargo, la banca estaba vacía.")
HIST = ("Julián prometió cuidar la planta de la sala. Se olvidó de regarla dos semanas. Cuando volvió, estaba seca. "
        "Triste, la regó y habló con su curso. Entre todos hicieron un turno de riego. A los quince días, brotó una hoja verde.")

