# ================================================================ OA 23 · clase 5
L(OA23, 5,
  "Este cuaderno y lápiz. Una persona de tu casa (o tú, en voz alta) lee el cuento breve de Julián.",
  "Aprenderé a escribir un comentario personal fundamentado sobre una obra escuchada. Sirve para expresar mi opinión con razones y evidencia.",
  ["Sé distinguir hechos de opiniones.", "Sé escuchar una obra completa."],
  ["Después de escuchar una obra, puedes responder con un comentario personal. Un comentario fundamentado tiene tres partes: tu opinión («me gustó que...»), una razón («porque...») y una evidencia del texto («por ejemplo, cuando...»). Sin razón ni evidencia, solo dices «me gustó» y el lector no sabe por qué.",
   "La opinión es lo que tú piensas o sientes; el hecho es lo que ocurre en la obra. «La planta se secó» es un hecho; «Me gustó que el curso se organizara» es una opinión. Las opiniones distintas son válidas si se apoyan en el texto. Dos personas pueden valorar distinto a un personaje, pero ambas deben mostrar en qué se basan.",
   "Un buen comentario también puede recomendar la obra: «Te la recomiendo porque enseña a cumplir lo que prometemos». Revísalo así: ¿dije qué pienso?, ¿di una razón?, ¿cité un hecho? Con eso, tu respuesta a lo escuchado es clara y sostenida."],
  [("comentario", "texto en que doy mi opinión sobre una obra"), ("opinión", "lo que pienso o siento"), ("razón", "motivo de mi opinión"), ("evidencia", "dato del texto que apoya mi opinión"), ("recomendar", "sugerir que alguien lea o escuche algo"), ("fundamentar", "apoyar con razones y datos")],
  [("Opinión y hecho", "¿«La planta se secó» es un hecho o una opinión?", ["Me pregunto si ocurre en el texto.", "Sí, ocurre en el cuento.", "Es un hecho."], "Es un hecho."),
   ("Comentario fundamentado", "«Me gustó que el curso se organizara porque hicieron un turno de riego.» ¿Qué partes tiene?", ["Opinión: me gustó.", "Razón: porque se organizó.", "Evidencia: hicieron un turno de riego."], "Opinión, razón y evidencia.")],
  [("Escribir solo «me gustó».", "No explica por qué.", "Agrega una razón y un dato del texto."),
   ("Inventar datos que el cuento no dice.", "Una opinión debe apoyarse en el texto.", "Cita lo que ocurre.")],
  ([E("¿Cuál es una opinión: «La planta se secó» o «Me gustó que el curso se organizara»?", "Me gustó que el curso se organizara", "Expresa lo que siente quien comenta."),
    E("¿Qué palabra introduce una razón: porque o pero?", "Porque", "Indica el motivo."),
    E("Un comentario que solo dice «me gustó», ¿está fundamentado?", "No", "No da razón ni evidencia.")],
   [E(f"Cuento: «{HIST}» ¿Qué dato sirve para fundamentar que el curso trabajó en equipo?", "Entre todos hicieron un turno de riego", "Muestra una acción en conjunto."),
    E("¿Qué valor muestra Julián al reconocer su error y actuar: responsabilidad o egoísmo?", "Responsabilidad", "Riega la planta y busca ayuda."),
    E(f"Cuento: «{HIST}» ¿A los cuántos días brotó una hoja verde?", "A los quince días", "Lo dice la última oración.")],
   [E("Completa: «Me gustó el final porque ___». ¿Cuál continuación es adecuada? A: «brotó una hoja verde después del cuidado». B: «tengo un perro».", "A", "A se apoya en el cuento."),
    E("¿Qué comentario está mejor fundamentado? A: «El cuento es bueno porque Julián reconoció su error y pidió ayuda a su curso.» B: «El cuento es bueno».", "A", "A da razón y evidencia."),
    E("En «Julián la regó y habló con su curso», ¿qué función cumple en un comentario: evidencia u opinión?", "Evidencia", "Es un dato del cuento.")],
   [E("Ema dice: «Julián fue irresponsable porque se olvidó dos semanas». Tomás dice: «Fue responsable porque corrigió su error». ¿Ambas opiniones pueden apoyarse en el cuento?", "Sí", "Cada una cita un hecho distinto del texto."),
    E("Dos personas opinan distinto sobre un cuento y ambas lo fundamentan con el texto. ¿Sus opiniones son válidas?", "Sí", "Las dos se apoyan en evidencia.")],
   [E("Recomiendas el cuento. ¿Qué frase es más útil? A: «Te lo recomiendo porque enseña a cumplir lo que prometemos». B: «Es largo».", "A", "A da una razón para leerlo."),
    E("Ordena las partes de un buen comentario: 1 evidencia, 2 opinión, 3 razón. Escribe el orden.", "2, 3, 1", "Primero opinas, luego das la razón y después la evidencia.")]),
  [E("Un compañero te pregunta qué te pareció el cuento de Julián. ¿Qué respuesta es mejor? A: «Me gustó porque el curso se organizó para regar la planta». B: «Bien».", "A", "Da una razón y un dato.")],
  [E("¿Qué partes tiene un comentario fundamentado?", "Opinión, razón y evidencia", "Así se sostiene lo que digo."),
   E("En Lenguaje: ¿Qué es una evidencia?", "Un dato del texto que apoya mi opinión", "Se puede citar de la obra."),
   E("¿Dos opiniones distintas pueden ser válidas?", "Sí", "Si ambas se apoyan en el texto.")],
  (f"Pide que lean este cuento: «{HIST}». Escribe un comentario de tres oraciones: tu opinión, la razón y un dato del cuento. Termina con una recomendación a otra persona.",
   "Me gustó el cuento porque Julián reconoció su error. Por ejemplo, regó la planta y pidió ayuda a su curso. Te lo recomiendo porque enseña a cumplir lo que prometemos.",
   ["da una opinión", "da una razón", "cita un dato del cuento", "recomienda"], ["tres oraciones y una recomendación"], ["solo decir «me gustó»", "inventar datos"],
   "Subraya la opinión, la razón y la evidencia en tu texto."),
  "Comenta oralmente a una persona de tu casa un cuento que hayas escuchado, con una razón.",
  "Escribe un comentario sobre un cuento que hayas escuchado en el colegio.")

