S_F = "Había una vez una rana que quería llegar a la luna. Saltó y saltó, pero solo llegó hasta la rama más alta del sauce."

L(OA24, 1,
  "Este cuaderno y lápiz. Una persona de tu casa puede leer en voz alta los textos de los ejercicios, o tú los lees en voz alta.",
  "Aprenderé a reconocer distintos tipos de textos orales, su propósito y qué sé ya sobre el tema. Sirve para saber cómo escuchar y qué buscar en cada uno.",
  ["Sé que escuchar es distinto de oír.", "Sé qué es un propósito."],
  ["Hay muchos textos orales y cada uno tiene un propósito. Una explicación aclara cómo funciona o por qué ocurre algo. Las instrucciones dicen los pasos para hacer algo. Una noticia informa de un hecho reciente. Un testimonio es el relato de alguien que vivió lo que cuenta. Una entrevista es una conversación de preguntas y respuestas. Un relato cuenta una historia.",
   "Identificar el tipo y el propósito te ayuda a decidir cómo escuchar. En las instrucciones importa el orden de los pasos; en una noticia, quién, qué, cuándo y dónde; en un testimonio, lo que sintió la persona; en una explicación, la causa y el resultado.",
   "Antes de escuchar, piensa qué sabes del tema. Esos conocimientos previos te ayudan a entender. Mientras escuchas, relaciona lo que oyes con tus experiencias: «yo también viví algo parecido». Esa conexión ayuda a recordar, pero no reemplaza lo que dice el texto."],
  [("texto oral", "mensaje que se dice y se escucha"), ("explicación", "texto que aclara cómo o por qué ocurre algo"), ("instrucciones", "pasos para hacer algo"), ("noticia", "texto que informa un hecho reciente"), ("testimonio", "relato de alguien que vivió algo"), ("entrevista", "conversación de preguntas y respuestas")],
  [("Tipo de texto", f"«{S_A}» ¿Qué tipo de texto oral es?", ["Veo que da pasos ordenados.", "Usa «primero», «luego» y «finalmente».", "Son instrucciones."], "Instrucciones."),
   ("Relacionar con la experiencia", f"Escuchas: «{S_D}». Pía dice: «Yo también me quedé tranquila cuando tembló». ¿Qué hizo Pía?", ["Compara lo que escuchó con lo que vivió.", "No inventó datos del texto.", "Relacionó lo oído con su experiencia."], "Relacionó lo escuchado con su experiencia.")],
  [("Escuchar todos los textos de la misma manera.", "Cada tipo tiene un propósito distinto.", "Identifica el tipo y qué buscar."),
   ("Usar solo mi experiencia y olvidar lo que dice el texto.", "Puedo cambiar el contenido.", "Relaciona, pero vuelve al texto.")],
  ([E(f"«{S_F}» ¿Qué tipo de texto oral es: relato, noticia o instrucciones?", "Relato", "Cuenta una historia."),
    E(f"«{S_B}» ¿Qué tipo de texto oral es: noticia o instrucciones?", "Noticia", "Informa de un hecho reciente."),
    E(f"«{S_C}» ¿Cuál es su propósito: explicar cómo las abejas ayudan a las plantas o contar un recuerdo?", "Explicar cómo las abejas ayudan a las plantas", "Aclara cómo ocurre algo.")],
   [E(f"«{S_D}» ¿Qué tipo de texto oral es: testimonio o noticia?", "Testimonio", "Habla alguien que lo vivió."),
    E(f"«{S_D}» ¿Quién habla: alguien que vivió el temblor o alguien que lo leyó en un diario?", "Alguien que lo vivió", "Dice «yo estuve»."),
    E(f"«{S_E}» ¿Qué tipo de texto oral es?", "Una entrevista", "Hay preguntas y respuestas.")],
   [E(f"«{S_A}» ¿Qué propósito tiene: enseñar los pasos para hacer algo o contar un recuerdo?", "Enseñar los pasos para hacer algo", "Son instrucciones con pasos ordenados."),
    E("Antes de escuchar un texto sobre abejas, ¿qué conocimiento previo te ayuda: saber que las abejas visitan flores o saber contar hasta mil?", "Saber que las abejas visitan flores", "Se relaciona con el tema."),
    E(f"«{S_B}» ¿Cuántos libros hay para préstamo?", "Cien", "Lo dice el texto.")],
   [E("¿Qué texto sirve para saber qué ocurrió anoche en el barrio: unas instrucciones o una noticia?", "Una noticia", "Informa de un hecho reciente."),
    E("Una explicación y un testimonio, ¿tienen el mismo propósito?", "No", "Uno aclara cómo ocurre algo y el otro cuenta lo vivido.")],
   [E(f"«{S_D}» Tomás dice: «Yo vi el temblor en una película». ¿Eso es parte de lo que dice el texto?", "No", "Es su experiencia, no aparece en el testimonio."),
    E(f"Si quieres armar el comedero de «{S_A}», ¿qué orden sigues: primero pegar y luego juntar, o primero juntar y luego pegar?", "Primero juntar y luego pegar", "Es el orden de los pasos.")]),
  [E("Escuchas en la radio: «La biblioteca abrirá el lunes a las nueve». ¿Qué tipo de texto es: noticia o entrevista?", "Noticia", "Informa un hecho.")],
  [E("En Lenguaje: ¿Qué es un testimonio?", "El relato de alguien que vivió lo que cuenta", "Habla en primera persona."),
   E("En Lenguaje: ¿Qué es una entrevista?", "Una conversación de preguntas y respuestas", "Una persona pregunta y otra responde."),
   E("¿Para qué sirve recordar lo que ya sé del tema?", "Para entender mejor lo que escucho", "Conecta lo nuevo con lo conocido.")],
  (f"Pide que lean estos textos y escribe de cada uno el tipo y el propósito: 1) «{S_A}» 2) «{S_B}» 3) «{S_C}» 4) «{S_D}». Anota un conocimiento previo o una experiencia que se relacione con uno de ellos.",
   "1) Instrucciones: enseñar pasos. 2) Noticia: informar. 3) Explicación: aclarar cómo ayudan las abejas. 4) Testimonio: contar lo vivido. Experiencia: una vez vi abejas en un jardín.",
   ["identifica el tipo de los cuatro", "indica el propósito", "relaciona uno con su experiencia"], ["cuatro tipos y una conexión"], ["confundir tipos", "no relacionar"],
   "Pide a alguien que lea otro texto breve y adivina el tipo antes de que termine."),
  "Escucha un aviso o una noticia en tu casa y di qué tipo de texto oral es.",
  "Inventa un texto oral breve de cada tipo: instrucciones y testimonio.")

