# ================================================================ OA 24 · clase 4
S_X = "Según el aviso de la escuela, la feria será el viernes a las 3 de la tarde en el patio."
S_Y = "Una vecina contó que había oído que la feria sería el sábado por la mañana."

L(OA24, 4,
  "Este cuaderno y lápiz. Una persona de tu casa puede leer en voz alta los textos de los ejercicios, o tú los lees en voz alta.",
  "Aprenderé a comparar información de dos textos orales: en qué coinciden, en qué se contradicen y cuál es más confiable. Sirve para no quedarme con un dato dudoso.",
  ["Sé localizar datos en un texto oral.", "Sé identificar la fuente de una información."],
  ["Comparar información dentro de un texto o entre dos textos ayuda a comprender mejor. Primero busca en qué coinciden: ¿hablan del mismo hecho? Luego busca en qué se diferencian: ¿cambia el día, el lugar, el número? Cuando dos datos no pueden ser verdad a la vez, se contradicen.",
   "Para decidir cuál creer, mira la fuente. Una fuente oficial, como el aviso de la escuela, suele ser más confiable que una persona que «había oído» algo. La expresión «había oído» indica información de segunda mano. Si dos fuentes dicen cosas distintas, pregunta para aclarar o busca una tercera fuente.",
   "No todos los textos sirven para lo mismo. Una explicación sirve para entender cómo funciona algo; un testimonio, para conocer una vivencia. Compara según el propósito. Y si dos textos usan palabras distintas pero dicen lo mismo, no se contradicen: solo lo expresan de otra manera."],
  [("coincidir", "decir lo mismo"), ("contradecirse", "decir cosas que no pueden ser verdad a la vez"), ("fuente", "origen de una información"), ("oficial", "que viene de una institución encargada del asunto"), ("de segunda mano", "información que alguien escuchó de otra persona"), ("confiable", "que merece confianza")],
  [("Comparar datos", f"Texto 1: «{S_X}» Texto 2: «{S_Y}» ¿Coinciden en el día?", ["Texto 1: viernes.", "Texto 2: sábado.", "No coinciden."], "No: uno dice viernes y otro sábado."),
   ("Elegir la fuente", "¿Cuál es más confiable: el aviso de la escuela o una vecina que había oído?", ["El aviso es oficial.", "La vecina da información de segunda mano.", "El aviso es más confiable."], "El aviso de la escuela.")],
  [("Creer el primer dato que escucho.", "Puede ser equivocado.", "Compara con otra fuente."),
   ("Pensar que dos textos con distintas palabras se contradicen siempre.", "Pueden decir lo mismo.", "Fíjate en los datos, no solo en las palabras.")],
  ([E(f"«{S_X}» ¿Qué día dice el aviso?", "El viernes", "Lo dice el texto."),
    E(f"«{S_Y}» ¿Qué día dice la vecina?", "El sábado", "Lo dice el texto."),
    E(f"«{S_X}» ¿A qué hora será la feria según el aviso?", "A las 3 de la tarde", "Lo dice el aviso.")],
   [E("¿En qué coinciden ambos textos sobre la feria?", "En que habrá una feria", "Los dos hablan del mismo evento."),
    E("¿Cuál texto es información de segunda mano: el aviso de la escuela o el de la vecina?", "El de la vecina", "Ella solo cuenta lo que había oído."),
    E("¿Qué indica «había oído»?", "Que es información de segunda mano", "No vio ni leyó el aviso.")],
   [E("¿Qué haces para saber el día correcto: preguntar a la escuela o elegir al azar?", "Preguntar a la escuela", "Es la fuente oficial."),
    E("El aviso dice que será a las 3 de la tarde; la vecina no dice hora. ¿Qué texto da más datos?", "El aviso", "Indica día, hora y lugar."),
    E(f"Según «{S_X}», ¿dónde será la feria?", "En el patio", "Lo dice el aviso.")],
   [E("Una noticia dice que a un mismo acto asistieron 40 personas y otra, que asistieron 50. ¿Se contradicen?", "Sí", "Las cifras no pueden ser ciertas a la vez."),
    E("Un texto dice «un perro grande» y otro, «un perro enorme». ¿Se contradicen?", "No", "Solo usan distintas palabras para lo mismo.")],
   [E("Texto 1 (explicación): «Las abejas llevan polen de flor en flor». Texto 2 (testimonio): «Una abeja se posó en mi mano y se fue». ¿Cuál sirve para explicar cómo ayudan a las plantas?", "El texto 1", "Explica el proceso."),
    E("Para resolver la diferencia entre el aviso y la vecina, ¿qué pregunta haces: «¿Cuál es el día confirmado por la escuela?» o «¿Te gusta la feria?»", "¿Cuál es el día confirmado por la escuela?", "Busca el dato verificable.")]),
  [E("En la radio dicen que una calle estará cerrada el lunes y en la municipalidad dicen que estará cerrada el martes. ¿Qué haces primero: confirmar con la municipalidad o elegir el día que más te acomode?", "Confirmar con la municipalidad", "Es la fuente oficial y permite comprobar el dato.")],
  [E("¿Qué significa que dos textos se contradicen?", "Que dicen cosas que no pueden ser verdad a la vez", "Por ejemplo, dos días distintos."),
   E("¿Qué fuente es más confiable: una oficial o una de segunda mano?", "La oficial", "Viene de quien organiza."),
   E("¿Qué comparas primero en dos textos?", "En qué coinciden", "Luego miras las diferencias.")],
  (f"Pide que lean estos dos textos: «{S_X}» y «{S_Y}». Escribe en qué coinciden, en qué se contradicen, cuál es más confiable y por qué, y una pregunta que harías para aclarar la diferencia.",
   "Coinciden en que habrá feria. Se contradicen en el día. Es más confiable el aviso porque es oficial. Pregunta: ¿Qué día confirma la escuela?",
   ["indica coincidencia", "indica contradicción", "justifica la fuente", "formula una pregunta"], ["cuatro anotaciones breves"], ["no justificar", "no distinguir fuentes"],
   "Subraya en los textos el dato que apoya cada respuesta."),
  "Compara dos avisos que escuches en tu casa o en la radio y anota en qué coinciden.",
  "Escribe dos textos de tres oraciones que se contradigan y explica cómo lo notaste.")

