S_P = "Los paneles solares transforman la luz del sol en electricidad. Se instalan en techos y en terrenos abiertos."

L(OA24, 5,
  "Este cuaderno y lápiz. Una persona de tu casa puede leer en voz alta el texto de los ejercicios, o tú lo lees en voz alta.",
  "Aprenderé a formular preguntas para comprender una idea, ampliarla o aclarar una palabra. Sirve para participar al escuchar y para entender mejor.",
  ["Sé localizar datos en textos orales.", "Sé que una pregunta lleva signos de interrogación."],
  ["Preguntar es una forma de comprender. Hay varios tipos de preguntas según lo que necesitas. Para aclarar una palabra: «¿Qué significa panel?». Para comprender una idea: «¿Qué quiere decir transformar luz en electricidad?». Para ampliar: «¿Dónde más se pueden instalar los paneles?». Para verificar tu comprensión: «¿Entendí bien que los paneles convierten la luz en electricidad?».",
   "Una buena pregunta es clara, respetuosa y se refiere a lo que se dijo. Las preguntas que se responden solo con «sí» o «no» dan poca información; las que empiezan con ¿cómo?, ¿por qué? o ¿para qué? permiten respuestas más completas. Pregunta en el momento adecuado: cuando termina la explicación o en una pausa, sin interrumpir.",
   "Puedes dirigirte al profesor o a un compañero. Si estás en una entrevista, ordena tus preguntas de las más generales a las más específicas. Evita preguntas que ofendan o que no tengan relación con el tema. Preguntar bien muestra que escuchaste y que quieres aprender."],
  [("pregunta abierta", "pregunta que permite una respuesta amplia"), ("pregunta cerrada", "pregunta que se responde con sí o no"), ("aclarar", "hacer algo más fácil de entender"), ("ampliar", "agregar más información"), ("verificar", "comprobar que algo es cierto"), ("entrevistado", "persona a quien se hacen preguntas")],
  [("Elegir la pregunta que amplía", f"«{S_P}» ¿Qué pregunta amplía la idea: «¿Dónde más se usan los paneles?» o «¿Sí?»", ["La primera pide más información.", "La segunda no aporta.", "Elijo la que amplía."], "«¿Dónde más se usan los paneles?»"),
   ("Verificar", "«¿Entendí bien que los paneles convierten la luz del sol en electricidad?» ¿Qué hace esta pregunta?", ["Repite la idea con otras palabras.", "Pide confirmación.", "Verifica la comprensión."], "Verifica que se entendió.")],
  [("Preguntar con «¿Sí?» o «¿Y?».", "No dice qué quiero saber.", "Formula una pregunta clara."),
   ("Preguntar sobre algo que no se dijo.", "No ayuda a comprender.", "Relaciona tu pregunta con el texto.")],
  ([E("«¿Qué significa panel?» ¿Qué tipo de pregunta es: aclarar una palabra o dar una opinión?", "Aclarar una palabra", "Pide un significado."),
    E(f"«{S_P}» ¿Qué pregunta ayuda a comprender mejor la idea: «¿Cómo transforman la luz en electricidad?» o «¿Hola?»", "¿Cómo transforman la luz en electricidad?", "Pide una explicación sobre el tema."),
    E("¿Puedes dirigir tu pregunta de comprensión tanto al profesor como a un compañero?", "Sí", "Puedes preguntar a cualquiera de los dos.")],
   [E(f"«{S_P}» ¿Qué pregunta aclara el sentido de «transforman»: «¿Qué quiere decir transformar?» o «¿Cuándo sale el sol?»", "¿Qué quiere decir transformar?", "Pide el significado."),
    E("¿Qué pregunta permite una respuesta más completa: «¿Funcionan los paneles?» o «¿Cómo funcionan los paneles?»", "¿Cómo funcionan los paneles?", "Empieza con ¿cómo? y pide explicación."),
    E("¿En qué momento conviene preguntar: cuando termina la explicación o interrumpiendo todo el tiempo?", "Cuando termina la explicación", "Así no se corta lo que se dice.")],
   [E("Quieres saber para qué sirve la electricidad que producen. ¿Qué pregunta usas: «¿Para qué se usa la electricidad que producen?» o «¿Qué día es hoy?»", "¿Para qué se usa la electricidad que producen?", "Tiene relación con el tema."),
    E(f"«{S_P}» ¿Qué pregunta amplía «se instalan en techos y en terrenos abiertos»: «¿Por qué se instalan en lugares abiertos?» o «¿Cómo te llamas?»", "¿Por qué se instalan en lugares abiertos?", "Pide una razón."),
    E("«¿Entendí bien que se instalan en techos?» ¿Es una pregunta para verificar o para opinar?", "Para verificar", "Repite la idea y pide confirmación.")],
   [E("A: «¿Qué es un panel solar?» B: «Esto no tiene sentido». ¿Cuál es una pregunta?", "A", "B es una opinión."),
    E("¿Qué pregunta demuestra que escuchaste? A: «Dijiste que se instalan en techos y terrenos abiertos; ¿en cuál sirven más?» B: «¿Qué dijiste?»", "A", "A se refiere a lo dicho.")],
   [E("Entrevista a un panadero. Ordena de lo general a lo específico: a) ¿Cómo se hace el pan? b) ¿Cuánto tiempo reposa la masa? c) ¿Qué trabajo hace usted? Escribe el orden.", "c, a, b", "Empieza por su trabajo, luego el proceso y luego un detalle."),
    E("¿Cuál NO es una pregunta adecuada para una entrevista: «¿Cuántos años lleva en este trabajo?» o «¿Es tonta esa idea?»", "¿Es tonta esa idea?", "Ofende a la persona entrevistada.")]),
  [E("Tu profesor explica cómo funciona un panel solar y no entiendes la palabra «instalar». ¿Qué preguntas: «¿Qué significa instalar?» o «¿Por qué hace calor?»", "¿Qué significa instalar?", "Aclara la palabra que no entendiste.")],
  [E("¿Para qué sirve una pregunta de aclaración?", "Para entender una palabra o idea", "Quita dudas sobre lo que se dijo."),
   E("¿Qué pregunta da una respuesta más completa: cerrada o abierta?", "Abierta", "Permite dar explicaciones más largas."),
   E("¿Cuándo conviene preguntar?", "En una pausa o al terminar", "Así respeto a quien habla.")],
  (f"Pide que lean este texto: «{S_P}». Escribe cuatro preguntas: una para aclarar una palabra, una para comprender una idea, una para ampliar y una para verificar tu comprensión. Luego hazlas a una persona y anota si te ayudaron.",
   "Aclarar: ¿Qué significa panel? Comprender: ¿Cómo transforman la luz en electricidad? Ampliar: ¿Dónde más se usan? Verificar: ¿Entendí bien que se instalan en techos?",
   ["cuatro preguntas de tipos distintos", "relacionadas con el texto", "respetuosas"], ["cuatro preguntas escritas y una nota"], ["preguntas de sí/no sin sentido", "preguntas sin relación"],
   "Revisa que cada pregunta se pueda responder con lo que quieres saber."),
  "Piensa dos preguntas para hacerle a alguien de tu casa sobre su trabajo o sus pasatiempos.",
  "Escribe cinco preguntas ordenadas de general a específica para una entrevista.")

# ================================================================ OA 24 · clase 6
S_D2 = "En el documental, un biólogo explica que algunas aves migran miles de kilómetros cada año para buscar alimento y un clima más cálido."

L(OA24, 6,
  "Este cuaderno y lápiz. Una persona de tu casa puede leer en voz alta el texto de los ejercicios, o tú lo lees en voz alta.",
  "Aprenderé a formular y fundamentar una opinión sobre lo que escucho, y a mejorarla con retroalimentación. Sirve para opinar con respeto y con razones.",
  ["Sé distinguir hechos de opiniones.", "Sé comparar información."],
  ["Después de escuchar, puedes dar tu opinión. Una opinión fundamentada tiene tres partes: lo que piensas, una razón y un dato de lo que escuchaste. «Me pareció interesante porque explica por qué migran las aves» es una opinión con razón. «Me gustó» es una opinión sin fundamento.",
   "Distingue hechos de opiniones. Un hecho es lo que el texto afirma: «Algunas aves migran miles de kilómetros». Una opinión es lo que tú piensas: «Me parece admirable». Tu opinión debe apoyarse en lo que dijo el texto: si dices que el documental es malo porque no te gustan las aves, no te basas en lo que escuchaste.",
   "Para mejorar, pide retroalimentación: que otra persona te diga qué está claro y qué falta. Una buena retroalimentación es concreta: «Tu opinión está clara; agrega un dato que escuchaste». Luego reescribe tu opinión con ese cambio. Respetar las opiniones distintas también es parte de escuchar."],
  [("opinión fundamentada", "opinión con razón y dato del texto"), ("hecho", "lo que el texto afirma"), ("razón", "motivo de una opinión"), ("retroalimentación", "comentario que ayuda a mejorar"), ("documental", "programa que muestra hechos reales"), ("migrar", "viajar de un lugar a otro en cierta época del año")],
  [("Hecho y opinión", f"«{S_D2}» ¿«Me parece admirable que vuelen tanto» es un hecho o una opinión?", ["Es lo que piensa quien comenta.", "No lo dice el documental.", "Es opinión."], "Una opinión."),
   ("Fundamentar", "¿Qué opinión está mejor fundamentada? A: «Me pareció interesante porque explicó por qué migran las aves.» B: «Me gustó.»", ["A da una razón.", "B no.", "A es mejor."], "A.")],
  [("Opinar sin razón.", "No se entiende por qué.", "Agrega «porque...» y un dato."),
   ("Basar la opinión en algo que no se dijo.", "No es justa con lo escuchado.", "Cita lo que oíste.")],
  ([E(f"«{S_D2}» ¿«Algunas aves migran miles de kilómetros» es un hecho o una opinión?", "Un hecho", "Lo afirma el documental."),
    E("«Me parece admirable que vuelen tanto.» ¿Es un hecho o una opinión?", "Una opinión", "Expresa lo que piensa quien habla."),
    E("¿Qué palabra introduce la razón de una opinión: porque o entonces?", "Porque", "Indica el motivo.")],
   [E(f"«{S_D2}» ¿Para qué migran las aves?", "Para buscar alimento y un clima más cálido", "Lo dice el documental."),
    E(f"«{S_D2}» ¿Quién entrega la información: un biólogo o un vecino?", "Un biólogo", "Lo dice el texto."),
    E("Una opinión fundamentada tiene opinión, razón y ¿qué más?", "Un dato de lo escuchado", "Apoya lo que digo.")],
   [E("¿Qué opinión está mejor fundamentada? A: «Me pareció interesante porque supe que algunas aves viajan miles de kilómetros.» B: «Es entretenido».", "A", "Da una razón con un dato."),
    E(f"¿Qué dato de «{S_D2}» apoya la opinión «las aves hacen viajes muy largos»?", "Miles de kilómetros", "Es el dato que indica la distancia."),
    E("Completa: «Creo que las aves migran porque ___». ¿Qué continuación se apoya en el texto: A «buscan alimento y un clima más cálido» o B «les gusta el frío»?", "A", "Lo dice el documental.")],
   [E("Ema dice: «Es aburrido» sin razón. Luis dice: «Es interesante porque cuentan cuánto viajan». ¿Quién fundamentó su opinión?", "Luis", "Da una razón con dato."),
    E("¿Qué retroalimentación ayuda más? A: «Tu opinión está clara; agrega un dato que escuchaste». B: «Está mal».", "A", "Dice qué mejorar.")],
   [E("¿Qué dos cosas le faltan a la opinión «Me gustó»?", "Una razón y un dato de lo escuchado", "Así queda fundamentada."),
    E("Pedro opina que el documental es malo porque «no me gusta ver aves». ¿Se basa en lo que escuchó?", "No", "Habla de su gusto, no del contenido.")]),
  [E("Un compañero opina distinto de ti sobre el documental. ¿Qué haces: escuchar su razón con respeto o decirle que está equivocado sin escucharlo?", "Escuchar su razón con respeto", "Escuchar es parte de opinar.")],
  [E("En Lenguaje: ¿Qué es una opinión fundamentada?", "Una opinión con razón y dato del texto", "Se apoya en lo escuchado."),
   E("En Lenguaje: ¿Qué es la retroalimentación?", "Un comentario que ayuda a mejorar", "Indica qué cambiar."),
   E("¿Un hecho y una opinión son lo mismo?", "No", "El hecho se afirma en el texto; la opinión es lo que pienso.")],
  (f"Pide que lean este texto: «{S_D2}». Escribe tu opinión en dos oraciones (opinión, razón y un dato que escuchaste). Pide a otra persona que te diga una cosa clara y una por mejorar, y reescribe tu opinión con ese cambio.",
   "Me pareció interesante porque explica por qué migran las aves. Por ejemplo, dice que viajan miles de kilómetros para buscar alimento. Me dijeron que agregara un dato; escribí cuánto viajan.",
   ["da opinión y razón", "incluye un dato del texto", "recibe retroalimentación", "reescribe"], ["opinión inicial y versión mejorada"], ["opinar sin razón", "no reescribir"],
   "Compara la primera y la segunda versión: ¿qué mejoró?"),
  "Cuéntale a alguien de tu casa un programa que viste y da una razón de tu opinión.",
  "Escribe una opinión fundamentada sobre una noticia que hayas escuchado.")
